export interface InstallOptions {
	readonly repoRoot: string;
	/** Allowlist spec; when omitted the boundary starts at zero privilege (everything denied). */
	readonly allowlist?: AllowlistSpec | Allowlist;
	readonly limits?: ResourceLimits;
	readonly ledger?: LedgerSink;
	readonly domainRegistry?: Readonly<Record<string, DomainSpec>>;
	readonly probe?: ProbeResult;
	readonly git?: GitRunner;
	readonly rollbackRehearsed?: boolean;
}

export interface InstalledBoundary {
	readonly boundary: SecurityBoundary;
	readonly snapshots: GitSnapshotManager;
	/** Wraps a dispatch table; the result is what may be handed to `KernelManager`. */
	readonly guard: (handlers: HostRequestHandlers) => {
		handlers: HostRequestHandlers;
		guarded: string[];
		denied: string[];
	};
	readonly probe: ProbeResult;
}

/**
 * Single registration entry point.
 *
 * Also ARMS the two upstream attachment points (construction A2 + dispatch A1). Before this call
 * both are inert, which is what makes the implant independently removable; after it there is no
 * agent-reachable disarm path.
 *
 * Order matters and is enforced by construction: probe the environment first (so the selected rung
 * is a measurement, never an assumption), then build the boundary with the allowlist, then derive
 * the domain proxy and the snapshot manager from that same boundary. There is no code path that
 * produces a domain proxy without a boundary or a boundary without a probe.
 */
export function installK3SecurityBoundary(options: InstallOptions): InstalledBoundary {
	const probe = options.probe ?? probeIsolation();
	const allowlist =
		options.allowlist instanceof Allowlist
			? options.allowlist
			: options.allowlist
				? new Allowlist(options.allowlist)
				: emptyAllowlist("install-default");
	const boundary = new SecurityBoundary({
		allowlist,
		limits: options.limits ?? DEFAULT_RESOURCE_LIMITS,
		ledger: options.ledger,
		repoRoot: options.repoRoot,
		probe,
	});
	const snapshots = new GitSnapshotManager({
		git: options.git ?? createGitRunner(options.repoRoot),
		ledger: options.ledger,
		rollbackRehearsed: options.rollbackRehearsed ?? false,
	});
	registerK3SecurityBoundary(boundary, options.domainRegistry ?? DOMAIN_REGISTRY);
	return {
		boundary,
		snapshots,
		probe,
		guard: (handlers) => guardHandlers(handlers, boundary, options.domainRegistry ?? DOMAIN_REGISTRY),
	};
}

/**
 * K3 implant 路 W1-T1 路 primary security boundary (Layer 1, 搂4.5.2) + resource limits (搂4.5.9).
 *
 * COMPONENT TRIPLE (verification_kernel.md 搂4.5.10)
 * - Reason to exist : the model's only tool is `ipython`, so the execution body is the WHOLE kernel
 *                     Python process. Per-command wrapping necessarily misses `os.system`; only an
 *                     OS primitive around the process covers the full execution surface.
 * - Axiom binding   : Axiom 1 (model-generated Python runs in-kernel with user privileges),
 *                     Axiom 5 (only environment-layer enforcement has non-zero strength).
 * - Deprecation     : NOT deprecable. The rung may be RAISED (gVisor / Firecracker) but never
 *                     lowered or removed. A downgrade is only legal when the probe proves the
 *                     higher rung is physically unavailable, and it must leave a change line.
 *
 * UPSTREAM PREMISE (non-negotiable, 搂4.5.1): `architecture.md` 鈥?"Workers and kernels are separate
 * processes for lifecycle and failure containment, not security sandboxes"; `rlm.md` 鈥?"The kernel
 * is a durable control environment, not a security sandbox". K3 must therefore build its own.
 *
 * NO OFF SWITCH: there is no `enabled` flag, no `--no-sandbox` argument, and no settings key in
 * this module. `wrapKernelSpawn` is the only way to build the kernel argv and it always applies the
 * best rung the probe found (contrast: the pi sandbox example ships `--no-sandbox`/`enabled:false`,
 * axiom7_enumeration.md Decision 1 J1).
 */

import { execFileSync } from "node:child_process";
import { accessSync, existsSync, constants as fsConstants, readFileSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import { type Allowlist, type Decision, emptyAllowlist } from "./allowlist.js";

/**
 * Isolation ladder rungs, strongest first (搂4.5.9 + the probe run in this sandbox).
 * `gvisor` / `firecracker` are the documented UPGRADE path, not the v10 baseline; the trigger is
 * "candidate evaluation starts executing genuinely untrusted third-party code".
 */
export type IsolationRung =
	| "firecracker" // upgrade path (KVM hardware isolation) 鈥?not v10 baseline
	| "gvisor" // upgrade path (syscall interception) 鈥?not v10 baseline
	| "landlock" // 搂4.5.2 preferred Linux primary boundary
	| "bwrap-namespaces" // mount+net namespace allowlist via bubblewrap
	| "seccomp-rlimit" // syscall filter + rlimit, userspace path guard
	| "seatbelt" // macOS implementation of Layer 1
	| "userspace"; // bottom rung: allowlist enforced in-process only

export const RUNG_ORDER: readonly IsolationRung[] = [
	"firecracker",
	"gvisor",
	"landlock",
	"bwrap-namespaces",
	"seccomp-rlimit",
	"seatbelt",
	"userspace",
];

export function rungStrength(rung: IsolationRung): number {
	return RUNG_ORDER.length - RUNG_ORDER.indexOf(rung);
}

export interface ProbeResult {
	readonly platform: NodeJS.Platform;
	readonly landlockAvailable: boolean;
	readonly landlockAbi?: number;
	readonly landlockReason?: string;
	readonly seccompAvailable: boolean;
	readonly bwrapPath?: string;
	readonly unprivilegedUserns: boolean;
	readonly cgroupWritable: boolean;
	readonly rlimitSettable: boolean;
	/** Highest rung the environment can actually enforce. */
	readonly selectedRung: IsolationRung;
	/** Populated when `selectedRung` is weaker than `landlock`: the change line's justification. */
	readonly downgradeReason?: string;
}

/** Resource ceilings applied per candidate sandbox (搂4.5.9). */
export interface ResourceLimits {
	/** Hard CPU seconds (RLIMIT_CPU). */
	readonly cpuSeconds: number;
	/** Address-space ceiling in bytes (RLIMIT_AS / cgroup memory.max). */
	readonly memoryBytes: number;
	/** Max processes (RLIMIT_NPROC). */
	readonly maxProcesses: number;
	/** Max open descriptors (RLIMIT_NOFILE). */
	readonly maxOpenFiles: number;
	/** Wall-clock ceiling for one kernel execution, ms. */
	readonly wallClockMs: number;
	/** Concurrent kernel ceiling. Upstream measured N=256 as a crash point; never widen. */
	readonly maxConcurrentKernels: number;
}

/**
 * Baseline limits for this environment: 2 cores / 7.8 GiB / no swap (OOM kills immediately),
 * so the memory ceiling leaves >= 1.5 GiB headroom. `maxConcurrentKernels` inherits the upstream
 * `boot-gate.ts` semaphore ceiling (direct spawn 64) 鈥?an already-measured boundary K3 must not widen.
 */
export const DEFAULT_RESOURCE_LIMITS: Readonly<ResourceLimits> = Object.freeze({
	cpuSeconds: 900,
	memoryBytes: 2 * 1024 * 1024 * 1024,
	maxProcesses: 256,
	maxOpenFiles: 1024,
	wallClockMs: 30 * 60 * 1000,
	maxConcurrentKernels: 64,
});

/** Ceilings that may never be widened, whatever a policy file says. */
export const ABSOLUTE_LIMIT_CEILINGS: Readonly<ResourceLimits> = Object.freeze({
	cpuSeconds: 3600,
	memoryBytes: 6 * 1024 * 1024 * 1024,
	maxProcesses: 1024,
	maxOpenFiles: 8192,
	wallClockMs: 60 * 60 * 1000,
	maxConcurrentKernels: 128,
});

