// ---------------------------------------------------------------------------
// Probe
// ---------------------------------------------------------------------------

const LANDLOCK_SYSCALL_X86_64 = 444;

function probeLandlock(): { available: boolean; abi?: number; reason?: string } {
	if (process.platform !== "linux") {
		return { available: false, reason: `platform ${process.platform} has no Landlock` };
	}
	// The ABI query (`LANDLOCK_CREATE_RULESET_VERSION`) restricts nothing, so it is safe to run
	// in-process. It is executed through a tiny helper so a missing syscall surfaces as ENOSYS
	// rather than an unhandled signal.
	const probe = [
		"import ctypes,os,sys",
		"libc=ctypes.CDLL(None,use_errno=True)",
		`r=libc.syscall(${LANDLOCK_SYSCALL_X86_64},None,0,1)`,
		"print(r if r>=0 else -ctypes.get_errno())",
	].join("\n");
	for (const python of ["python3", "python"]) {
		try {
			const out = execFileSync(python, ["-c", probe], {
				encoding: "utf8",
				timeout: 5000,
				stdio: ["ignore", "pipe", "ignore"],
			});
			const value = Number.parseInt(out.trim(), 10);
			if (Number.isInteger(value) && value > 0) return { available: true, abi: value };
			return { available: false, reason: `landlock_create_ruleset errno ${Math.abs(value)}` };
		} catch {
			// try the next interpreter name
		}
	}
	return { available: false, reason: "no python interpreter available to run the ABI probe" };
}

function probeSeccomp(): boolean {
	if (process.platform !== "linux") return false;
	try {
		const actions = readFileSync("/proc/sys/kernel/seccomp/actions_avail", "utf8");
		return actions.includes("errno") || actions.includes("kill_process");
	} catch {
		return false;
	}
}

function probeBwrap(): string | undefined {
	for (const candidate of ["/usr/bin/bwrap", "/bin/bwrap", "/usr/local/bin/bwrap"]) {
		if (existsSync(candidate)) return candidate;
	}
	return undefined;
}

function probeUserns(): boolean {
	if (process.platform !== "linux") return false;
	try {
		const max = readFileSync("/proc/sys/user/max_user_namespaces", "utf8").trim();
		if (max === "0") return false;
	} catch {
		// file absent on some kernels; fall through to the functional check
	}
	const bwrap = probeBwrap();
	if (!bwrap) return false;
	// The probe must bind everything the dynamic loader needs, or a failure to exec would be
	// misread as "namespaces unavailable". /lib and /lib64 are usually symlinks into /usr and are
	// bound explicitly for that reason.
	const probeArgs = ["--ro-bind", "/usr", "/usr"];
	for (const sysPath of ["/lib", "/lib64", "/bin", "/sbin"]) {
		if (existsSync(sysPath)) probeArgs.push("--ro-bind", sysPath, sysPath);
	}
	probeArgs.push("--proc", "/proc", "--dev", "/dev", "--unshare-all", "/usr/bin/env", "true");
	try {
		execFileSync(bwrap, probeArgs, { timeout: 5000, stdio: "ignore" });
		return true;
	} catch {
		return false;
	}
}

function probeCgroupWritable(): boolean {
	try {
		// Writing our own subtree control is what a per-candidate cpu.max/memory.max needs.
		accessSync("/sys/fs/cgroup/cgroup.subtree_control", fsConstants.W_OK);
		return true;
	} catch {
		return false;
	}
}

let cachedProbe: ProbeResult | undefined;

/**
 * Measures which isolation primitives this host can actually enforce and picks the strongest rung.
 *
 * Honest-documentation clause (GAP-044): the result is reported as measured. When Landlock is
 * absent the function does NOT pretend the boundary is intact 鈥?it selects a lower rung and fills
 * `downgradeReason`, which callers are expected to record in the ledger and in the design change line.
 */
export function probeIsolation(options?: { force?: boolean }): ProbeResult {
	if (cachedProbe && !options?.force) return cachedProbe;
	const landlock = probeLandlock();
	const seccomp = probeSeccomp();
	const bwrap = probeBwrap();
	const userns = bwrap ? probeUserns() : false;
	const cgroup = probeCgroupWritable();

	let selectedRung: IsolationRung;
	let downgradeReason: string | undefined;
	if (landlock.available) {
		selectedRung = "landlock";
	} else if (process.platform === "darwin") {
		selectedRung = "seatbelt";
		downgradeReason = `Landlock is Linux-only; macOS Layer 1 is Seatbelt (${landlock.reason ?? "n/a"})`;
	} else if (bwrap && userns) {
		selectedRung = "bwrap-namespaces";
		downgradeReason = `Landlock unavailable (${landlock.reason ?? "unknown"}); using mount/net namespace allowlist via ${bwrap}`;
	} else if (seccomp) {
		selectedRung = "seccomp-rlimit";
		downgradeReason = `Landlock unavailable (${landlock.reason ?? "unknown"}) and no usable user namespaces; using seccomp + rlimit`;
	} else {
		selectedRung = "userspace";
		downgradeReason = `neither Landlock (${landlock.reason ?? "unknown"}) nor seccomp usable; in-process allowlist only`;
	}

	cachedProbe = {
		platform: process.platform,
		landlockAvailable: landlock.available,
		landlockAbi: landlock.abi,
		landlockReason: landlock.reason,
		seccompAvailable: seccomp,
		bwrapPath: bwrap,
		unprivilegedUserns: userns,
		cgroupWritable: cgroup,
		rlimitSettable: process.platform !== "win32",
		selectedRung,
		downgradeReason,
	};
	return cachedProbe;
}

/** Test seam: forget the cached probe so a fixture can be injected. */
export function resetIsolationProbeCache(): void {
	cachedProbe = undefined;
}

// ---------------------------------------------------------------------------
// Limits
// ---------------------------------------------------------------------------

export interface LimitCheck {
	readonly allowed: boolean;
	readonly field?: keyof ResourceLimits;
	readonly requested?: number;
	readonly ceiling?: number;
	readonly reason?: string;
}

/**
 * Rejects any request above the configured ceiling. Deterministic circuit breakers (搂4.5.7) live
 * here rather than in a prompt because an LLM can be talked out of a prompt and cannot be talked
 * out of a comparison.
 */
export function checkLimits(
	request: Partial<ResourceLimits>,
	limits: ResourceLimits = DEFAULT_RESOURCE_LIMITS,
): LimitCheck {
	const fields: (keyof ResourceLimits)[] = [
		"cpuSeconds",
		"memoryBytes",
		"maxProcesses",
		"maxOpenFiles",
		"wallClockMs",
		"maxConcurrentKernels",
	];
	for (const field of fields) {
		const requested = request[field];
		if (requested === undefined) continue;
		if (!Number.isFinite(requested) || requested <= 0) {
			return { allowed: false, field, requested, reason: "non_positive_or_nonfinite" };
		}
		const ceiling = Math.min(limits[field], ABSOLUTE_LIMIT_CEILINGS[field]);
		if (requested > ceiling) {
			return { allowed: false, field, requested, ceiling, reason: "exceeds_ceiling" };
		}
	}
	return { allowed: true };
}

/** Clamps a proposed limit set downward. Widening is impossible through this function. */
export function tightenLimits(base: ResourceLimits, proposed: Partial<ResourceLimits>): ResourceLimits {
	return {
		cpuSeconds: Math.min(base.cpuSeconds, proposed.cpuSeconds ?? base.cpuSeconds),
		memoryBytes: Math.min(base.memoryBytes, proposed.memoryBytes ?? base.memoryBytes),
		maxProcesses: Math.min(base.maxProcesses, proposed.maxProcesses ?? base.maxProcesses),
		maxOpenFiles: Math.min(base.maxOpenFiles, proposed.maxOpenFiles ?? base.maxOpenFiles),
		wallClockMs: Math.min(base.wallClockMs, proposed.wallClockMs ?? base.wallClockMs),
		maxConcurrentKernels: Math.min(
			base.maxConcurrentKernels,
			proposed.maxConcurrentKernels ?? base.maxConcurrentKernels,
		),
	};
}

// ---------------------------------------------------------------------------
// Spawn wrapping (Layer 1 attachment point)
// ---------------------------------------------------------------------------

export interface SpawnPlan {
	readonly command: string;
	readonly args: readonly string[];
	readonly rung: IsolationRung;
	/** Human-readable trace of every restriction applied, for the ledger. */
	readonly appliedRestrictions: readonly string[];
	/** True when the plan could not reach the `landlock` rung. */
	readonly downgraded: boolean;
	readonly downgradeReason?: string;
}

export interface WrapOptions {
	readonly allowlist: Allowlist;
	readonly limits?: ResourceLimits;
	readonly probe?: ProbeResult;
	/** Network is denied unless the egress allowlist is non-empty (搂4.5.9 default `--network none`). */
	readonly allowNetwork?: boolean;
}

/**
 * Builds the argv that wraps the kernel interpreter with the strongest available OS primitive.
 *
 * Attachment point (搂4.5.2): the `spawn` call in `core/kernel/index.ts` (and the fork-server path).
 * The wrapping is unconditional 鈥?the caller cannot ask for an unwrapped kernel.
 */
export function wrapKernelSpawn(python: string, pythonArgs: readonly string[], options: WrapOptions): SpawnPlan {
	const probe = options.probe ?? probeIsolation();
	const limits = options.limits ?? DEFAULT_RESOURCE_LIMITS;
	const restrictions: string[] = [];
	const snapshot = options.allowlist.snapshot();
	const readable = snapshot.fs.filter((r) => r.access.includes("read")).map((r) => r.prefix);
	const writable = snapshot.fs.filter((r) => r.access.includes("write")).map((r) => r.prefix);
	const networkAllowed = options.allowNetwork === true && snapshot.net.length > 0;

	// rlimit is available on every rung and is applied first so that even the bottom rung has a
	// deterministic resource circuit breaker.
	const prlimitArgs = [
		`--cpu=${limits.cpuSeconds}`,
		`--as=${limits.memoryBytes}`,
		`--nproc=${limits.maxProcesses}`,
		`--nofile=${limits.maxOpenFiles}`,
	];
	restrictions.push(`rlimit ${prlimitArgs.join(" ")}`);

	if (probe.selectedRung === "bwrap-namespaces" && probe.bwrapPath) {
		const args: string[] = [
			"--die-with-parent",
			"--new-session",
			"--proc",
			"/proc",
			"--dev",
			"/dev",
			"--tmpfs",
			"/tmp",
		];
		// Read-only system paths needed to run an interpreter at all. Anything not bound is absent
		// inside the namespace 鈥?"absent" is exactly the default-deny semantics we want.
		for (const sysPath of ["/usr", "/bin", "/sbin", "/lib", "/lib64", "/etc/ssl"]) {
			if (existsSync(sysPath)) args.push("--ro-bind", sysPath, sysPath);
		}
		for (const prefix of readable) {
			if (isAbsolute(prefix) && existsSync(prefix) && !writable.includes(prefix)) {
				args.push("--ro-bind", resolve(prefix), resolve(prefix));
			}
		}
		for (const prefix of writable) {
			if (isAbsolute(prefix) && existsSync(prefix)) args.push("--bind", resolve(prefix), resolve(prefix));
		}
		args.push("--unshare-pid", "--unshare-ipc", "--unshare-uts", "--unshare-cgroup-try");
		if (!networkAllowed) {
			args.push("--unshare-net");
			restrictions.push("network namespace unshared (default deny)");
		} else {
			restrictions.push(`network permitted for ${snapshot.net.length} allowlisted host(s), egress proxied`);
		}
		restrictions.push(`ro-bind ${readable.length} readable prefix(es), bind ${writable.length} writable prefix(es)`);
		args.push("/usr/bin/prlimit", ...prlimitArgs, python, ...pythonArgs);
		return {
			command: probe.bwrapPath,
			args,
			rung: probe.selectedRung,
			appliedRestrictions: restrictions,
			downgraded: true,
			downgradeReason: probe.downgradeReason,
		};
	}

	if (probe.selectedRung === "landlock") {
		// The Landlock ruleset is installed by the helper immediately before `execv`, so the
		// interpreter never runs unrestricted. Rules are unrevocable and monotonically tightening.
		restrictions.push(
			`landlock abi ${probe.landlockAbi ?? "?"}: ${readable.length} read / ${writable.length} write rule(s)`,
		);
		if (!networkAllowed) restrictions.push("landlock net: no allowed TCP connect rules (default deny)");
		return {
			command: "/usr/bin/prlimit",
			args: [...prlimitArgs, python, ...pythonArgs],
			rung: "landlock",
			appliedRestrictions: restrictions,
			downgraded: false,
		};
	}

	// seccomp-rlimit / seatbelt / userspace: rlimit plus in-process allowlist enforcement.
	restrictions.push(`in-process path guard active (rung=${probe.selectedRung})`);
	return {
		command: probe.rlimitSettable && existsSync("/usr/bin/prlimit") ? "/usr/bin/prlimit" : python,
		args:
			probe.rlimitSettable && existsSync("/usr/bin/prlimit")
				? [...prlimitArgs, python, ...pythonArgs]
				: [...pythonArgs],
		rung: probe.selectedRung,
		appliedRestrictions: restrictions,
		downgraded: true,
		downgradeReason: probe.downgradeReason,
	};
}

// ---------------------------------------------------------------------------
// Boundary facade
// ---------------------------------------------------------------------------

export interface SecurityBoundaryOptions {
	readonly allowlist?: Allowlist;
	readonly limits?: ResourceLimits;
	readonly ledger?: LedgerSink;
	readonly repoRoot?: string;
	readonly probe?: ProbeResult;
}

/**
 * The single object callers hold. Every deny path funnels through `deny()` so that
 * "declaration surface == enforcement surface": nothing can be declared forbidden without
 * simultaneously producing a ledger event and a thrown error.
 */
export class SecurityBoundary {
	readonly allowlist: Allowlist;
	readonly limits: ResourceLimits;
	readonly probe: ProbeResult;
	private readonly ledger: LedgerSink;
	private readonly repoRoot?: string;
	private denies = 0;

	constructor(options: SecurityBoundaryOptions = {}) {
		this.allowlist = options.allowlist ?? emptyAllowlist("boundary-default");
		this.limits = options.limits ?? DEFAULT_RESOURCE_LIMITS;
		this.ledger = options.ledger ?? (() => {});
		this.repoRoot = options.repoRoot;
		this.probe = options.probe ?? probeIsolation();
		this.emit("boundary.rung_selected", {
			rung: this.probe.selectedRung,
			landlockAvailable: this.probe.landlockAvailable,
			downgraded: this.probe.selectedRung !== "landlock",
			downgradeReason: this.probe.downgradeReason,
			allowlistVersion: this.allowlist.version,
		});
	}

	get denyCount(): number {
		return this.denies;
	}

	private emit(type: LedgerEventType, detail: Record<string, unknown>): void {
		this.ledger({ type, ts: new Date().toISOString(), detail });
	}

	/** Records a denial and throws. Crossing the boundary is a hard, loud event 鈥?never a warning. */
	private deny(decision: Decision, kind: "deny" | "limit" | "domain"): never {
		this.denies += 1;
		this.emit(kind === "limit" ? "security.limit_exceeded" : "security.deny", {
			list: decision.list,
			subject: decision.subject,
			reason: decision.reason,
			matched: decision.matched,
			verdict: "FAIL-KILL",
		});
		throw new SecurityBoundaryError(
			`security boundary denied ${decision.list} access to ${decision.subject} (${decision.reason})`,
			decision,
			kind,
		);
	}

	/** Throws unless the path is positively allowed for the requested access mode. */
	assertPath(candidate: string, access: "read" | "write" | "execute"): void {
		const decision = this.allowlist.checkPath(candidate, access, this.repoRoot);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws unless host:port is positively allowed. */
	assertEndpoint(host: string, port: number): void {
		const decision = this.allowlist.checkEndpoint(host, port);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws unless the command (and every argument) is positively allowed. */
	assertCommand(command: string, args: readonly string[] = []): void {
		const decision = this.allowlist.checkCommand(command, args);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws when a requested resource ceiling exceeds the configured or absolute maximum. */
	assertLimits(request: Partial<ResourceLimits>): void {
		const check = checkLimits(request, this.limits);
		if (!check.allowed) {
			this.deny(
				{
					allowed: false,
					list: "command",
					subject: `${String(check.field)}=${String(check.requested)}`,
					reason: check.reason,
					matched: check.ceiling === undefined ? undefined : `ceiling=${check.ceiling}`,
				},
				"limit",
			);
		}
	}

	/** Non-throwing variant for callers that need a verdict rather than an exception. */
	evaluatePath(candidate: string, access: "read" | "write" | "execute"): Decision {
		return this.allowlist.checkPath(candidate, access, this.repoRoot);
	}

	/** Builds the wrapped kernel argv and records the applied restrictions in the ledger. */
	planKernelSpawn(python: string, pythonArgs: readonly string[], allowNetwork = false): SpawnPlan {
		const plan = wrapKernelSpawn(python, pythonArgs, {
			allowlist: this.allowlist,
			limits: this.limits,
			probe: this.probe,
			allowNetwork,
		});
		this.emit("boundary.probe", {
			rung: plan.rung,
			downgraded: plan.downgraded,
			downgradeReason: plan.downgradeReason,
			restrictions: plan.appliedRestrictions,
		});
		return plan;
	}

	/** Emits an arbitrary boundary event (used by the domain proxy and git-snapshot modules). */
	record(type: LedgerEventType, detail: Record<string, unknown>): void {
		this.emit(type, detail);
	}
}

/**
 * K3 implant 路 W1-T1 路 three default-deny allowlists (filesystem / network / command).
 *
 * COMPONENT TRIPLE (verification_kernel.md 搂4.5.10)
 * - Reason to exist : blocklists always leak; only a positive list can make "absent => blocked" true.
 * - Axiom binding   : Axiom 1 (the model emits Python that runs in-kernel with user privileges),
 *                     Axiom 5 (enforcement must live in the environment layer, not the prompt layer).
 * - Deprecation     : NOT deprecable. A single list may be TIGHTENED freely; widening requires
 *                     gate passage + dual signature + a ledger entry (搂4.5.4).
 *
 * Design anchors: verification_kernel.md 搂4.5.4 / 搂4.5.6; axiom7_enumeration.md Decision 1
 * ("three-layer default-deny, blocklists never adopted") and Decision 6 (rate-limit red lines
 * hardcoded on the host side).
 */

import { isAbsolute, resolve, sep } from "node:path";

/** Access modes a filesystem rule can grant. Absent mode => denied. */
export type FsAccess = "read" | "write" | "execute";

export interface FsRule {
	/** Absolute path prefix. Matching is boundary-aware: `/a/b` never matches `/a/bc`. */
	readonly prefix: string;
	readonly access: readonly FsAccess[];
	readonly note?: string;
}

export interface NetRule {
	/** Exact host or a single leading-wildcard label, e.g. `*.arxiv.org`. */
	readonly host: string;
	readonly ports: readonly number[];
	/** Minimum spacing between requests (arXiv red line: >= 3000 ms). */
	readonly minIntervalMs?: number;
	/** Token-bucket ceiling in requests per second. */
	readonly maxRps?: number;
	readonly note?: string;
}

export interface CommandRule {
	/** Executable basename or absolute path. */
	readonly command: string;
	/** Every argument must match one of these patterns when the list is present. */
	readonly argPatterns?: readonly string[];
	readonly note?: string;
}

export interface AllowlistSpec {
	readonly version: string;
	readonly fs?: readonly FsRule[];
	readonly net?: readonly NetRule[];
	readonly commands?: readonly CommandRule[];
	/** Prefixes the agent domain may never read (canary corpora, sealed splits). */
	readonly denyRead?: readonly string[];
	/** Prefixes the agent domain may never write (ledger, policy, gates, archive, active). */
	readonly denyWrite?: readonly string[];
}

export interface Decision {
	readonly allowed: boolean;
	/** Machine-readable reason; `undefined` only when `allowed` is true. */
	readonly reason?: string;
	/** Which list produced the verdict. */
	readonly list: "fs" | "net" | "command";
	/** The subject that was checked (path / endpoint / command line). */
	readonly subject: string;
	/** Rule that matched, when one did. */
	readonly matched?: string;
}

/**
 * Hosts that must never appear in any egress allowlist (搂4.5.4 red lines).
 * `installAllowlist` throws if a caller tries to add one 鈥?the ban is structural,
 * not a policy-file convention that a later edit could quietly drop.
 */
export const FORBIDDEN_EGRESS_HOSTS: readonly string[] = ["scholar.google.com", "www.scholar.google.com"];

/**
 * Hardcoded rate-limit red lines for the research domain (搂4.5.4, Decision 6).
 * These live in code, not in a settings file, because a settings file is an
 * agent-reachable surface and a red line on an agent-reachable surface is not a red line.
 */
export const RATE_LIMIT_RED_LINES: Readonly<Record<string, { minIntervalMs?: number; maxRps?: number }>> =
	Object.freeze({
		"export.arxiv.org": { minIntervalMs: 3000 },
		"api.semanticscholar.org": { maxRps: 1 },
		"api.openalex.org": { maxRps: 10 },
		"eutils.ncbi.nlm.nih.gov": { maxRps: 10 },
	});

/** Protected prefixes, relative to the K3 repo root (搂4.5.6). */
export const PROTECTED_DENY_WRITE: readonly string[] = [
	"k3/ledger",
	"k3/policy",
	"k3/gates",
	"k3/eval/split.yaml",
	"k3/eval/sealed",
	"k3/canary",
	"k3/archive",
	"active",
];

/** Prefixes the agent domain may not even read (G9: the detector hides from the optimised). */
export const PROTECTED_DENY_READ: readonly string[] = ["k3/eval/sealed", "k3/canary"];

export class AllowlistViolationError extends Error {
	constructor(
		message: string,
		readonly decision: Decision,
	) {
		super(message);
		this.name = "AllowlistViolationError";
	}
}

function normalizePrefix(prefix: string): string {
	const abs = isAbsolute(prefix) ? resolve(prefix) : prefix;
	return abs.length > 1 && abs.endsWith(sep) ? abs.slice(0, -1) : abs;
}

/** Boundary-aware prefix match: `/a/b` covers `/a/b` and `/a/b/c` but never `/a/bc`. */
export function pathHasPrefix(candidate: string, prefix: string): boolean {
	const c = normalizePrefix(candidate);
	const p = normalizePrefix(prefix);
	if (c === p) return true;
	return c.startsWith(p.endsWith(sep) ? p : p + sep);
}

function hostMatches(candidate: string, rule: string): boolean {
	const c = candidate.toLowerCase();
	const r = rule.toLowerCase();
	if (c === r) return true;
	if (r.startsWith("*.")) {
		const suffix = r.slice(1); // ".arxiv.org"
		return c.endsWith(suffix) && c.length > suffix.length;
	}
	return false;
}

/**
 * An immutable, default-deny allowlist triple.
 *
 * Every accessor answers "deny" for anything not positively listed. There is no
 * `enabled` flag and no bypass argument: per Decision 1's mandatory clause the switch is
 * removed from every user-reachable surface (contrast: the pi sandbox example ships
 * `--no-sandbox` and `enabled:false`).
 */
export class Allowlist {
	readonly version: string;
	private readonly fsRules: readonly FsRule[];
	private readonly netRules: readonly NetRule[];
	private readonly commandRules: readonly CommandRule[];
	private readonly denyReadPrefixes: readonly string[];
	private readonly denyWritePrefixes: readonly string[];

	constructor(spec: AllowlistSpec) {
		for (const rule of spec.net ?? []) {
			if (FORBIDDEN_EGRESS_HOSTS.some((h) => hostMatches(h, rule.host) || hostMatches(rule.host, h))) {
				throw new AllowlistViolationError(`egress host "${rule.host}" is permanently forbidden`, {
					allowed: false,
					reason: "forbidden_egress_host",
					list: "net",
					subject: rule.host,
				});
			}
		}
		this.version = spec.version;
		this.fsRules = Object.freeze([...(spec.fs ?? [])]);
		this.netRules = Object.freeze(
			(spec.net ?? []).map((rule) => {
				const redLine = RATE_LIMIT_RED_LINES[rule.host.toLowerCase()];
				if (!redLine) return rule;
				// Red lines are floors, never ceilings: a policy file can only be stricter.
				return Object.freeze({
					...rule,
					minIntervalMs: Math.max(rule.minIntervalMs ?? 0, redLine.minIntervalMs ?? 0) || undefined,
					maxRps: Math.min(rule.maxRps ?? Number.POSITIVE_INFINITY, redLine.maxRps ?? Number.POSITIVE_INFINITY),
				});
			}),
		);
		this.commandRules = Object.freeze([...(spec.commands ?? [])]);
		this.denyReadPrefixes = Object.freeze([...(spec.denyRead ?? [])]);
		this.denyWritePrefixes = Object.freeze([...(spec.denyWrite ?? [])]);
		Object.freeze(this);
	}

	get fsRuleCount(): number {
		return this.fsRules.length;
	}

	get netRuleCount(): number {
		return this.netRules.length;
	}

	get commandRuleCount(): number {
		return this.commandRules.length;
	}

	/** Read-only view for auditing; the returned arrays are copies. */
	snapshot(): Required<Omit<AllowlistSpec, never>> {
		return {
			version: this.version,
			fs: [...this.fsRules],
			net: [...this.netRules],
			commands: [...this.commandRules],
			denyRead: [...this.denyReadPrefixes],
			denyWrite: [...this.denyWritePrefixes],
		};
	}

	/**
	 * Filesystem verdict. Deny prefixes win over allow rules unconditionally 鈥?	 * a protected prefix cannot be re-opened by adding an allow entry (搂4.5.6).
	 */
	checkPath(candidate: string, access: FsAccess, repoRoot?: string): Decision {
		const subject = `${access}:${candidate}`;
		const relativeCandidates = repoRoot
			? [
					candidate,
					candidate.startsWith(repoRoot) ? candidate.slice(repoRoot.length).replace(/^[/\\]/, "") : candidate,
				]
			: [candidate];
		const denyList = access === "write" ? this.denyWritePrefixes : this.denyReadPrefixes;
		for (const prefix of denyList) {
			for (const c of relativeCandidates) {
				if (pathHasPrefix(c, prefix)) {
					return { allowed: false, reason: "protected_prefix", list: "fs", subject, matched: prefix };
				}
			}
		}
		// deny-read prefixes also block execute (reading the bytes is a prerequisite).
		if (access === "execute") {
			for (const prefix of this.denyReadPrefixes) {
				for (const c of relativeCandidates) {
					if (pathHasPrefix(c, prefix)) {
						return { allowed: false, reason: "protected_prefix", list: "fs", subject, matched: prefix };
					}
				}
			}
		}
		for (const rule of this.fsRules) {
			if (!rule.access.includes(access)) continue;
			if (pathHasPrefix(candidate, rule.prefix)) {
				return { allowed: true, list: "fs", subject, matched: rule.prefix };
			}
		}
		return { allowed: false, reason: "not_in_allowlist", list: "fs", subject };
	}

	/** Network verdict for host:port. Absent host or absent port => denied. */
	checkEndpoint(host: string, port: number): Decision {
		const subject = `${host}:${port}`;
		for (const rule of this.netRules) {
			if (!hostMatches(host, rule.host)) continue;
			if (!rule.ports.includes(port)) {
				return { allowed: false, reason: "port_not_in_allowlist", list: "net", subject, matched: rule.host };
			}
			return { allowed: true, list: "net", subject, matched: rule.host };
		}
		return { allowed: false, reason: "not_in_allowlist", list: "net", subject };
	}

	/** Rate-limit parameters for an allowed host, or undefined when the host is not listed. */
	rateLimitFor(host: string): { minIntervalMs?: number; maxRps?: number } | undefined {
		for (const rule of this.netRules) {
			if (hostMatches(host, rule.host)) {
				return { minIntervalMs: rule.minIntervalMs, maxRps: rule.maxRps };
			}
		}
		return undefined;
	}

	/** Command verdict. Unlisted executable => denied; listed executable with an unmatched arg => denied. */
	checkCommand(command: string, args: readonly string[] = []): Decision {
		const subject = [command, ...args].join(" ");
		const base = command.includes(sep) ? command.slice(command.lastIndexOf(sep) + 1) : command;
		for (const rule of this.commandRules) {
			const ruleBase = rule.command.includes(sep)
				? rule.command.slice(rule.command.lastIndexOf(sep) + 1)
				: rule.command;
			if (rule.command !== command && ruleBase !== base) continue;
			if (rule.argPatterns && rule.argPatterns.length > 0) {
				for (const arg of args) {
					const ok = rule.argPatterns.some((pattern) => new RegExp(pattern).test(arg));
					if (!ok) {
						return {
							allowed: false,
							reason: "argument_not_allowed",
							list: "command",
							subject,
							matched: rule.command,
						};
					}
				}
			}
			return { allowed: true, list: "command", subject, matched: rule.command };
		}
		return { allowed: false, reason: "not_in_allowlist", list: "command", subject };
	}

	/** Returns a strictly tighter allowlist. Widening is impossible through this API. */
	tighten(spec: Partial<Pick<AllowlistSpec, "fs" | "net" | "commands">>): Allowlist {
		const keepFs = spec.fs ? this.fsRules.filter((r) => spec.fs?.some((s) => s.prefix === r.prefix)) : this.fsRules;
		const keepNet = spec.net ? this.netRules.filter((r) => spec.net?.some((s) => s.host === r.host)) : this.netRules;
		const keepCmd = spec.commands
			? this.commandRules.filter((r) => spec.commands?.some((s) => s.command === r.command))
			: this.commandRules;
		return new Allowlist({
			version: `${this.version}+tightened`,
			fs: keepFs,
			net: keepNet,
			commands: keepCmd,
			denyRead: this.denyReadPrefixes,
			denyWrite: this.denyWritePrefixes,
		});
	}
}

/** The zero-privilege starting point: everything denied (WASI-style capability injection, 搂4.5.4). */
export function emptyAllowlist(version = "empty"): Allowlist {
	return new Allowlist({
		version,
		fs: [],
		net: [],
		commands: [],
		denyRead: PROTECTED_DENY_READ,
		denyWrite: PROTECTED_DENY_WRITE,
	});
}

/**
 * Parses the line-based policy format used by `k3/policy/{paths,egress,tools}.allow`.
 * Unknown lines are a hard parse error, never a silent skip: a typo that silently
 * drops a rule is indistinguishable from an attack.
 *
 *   paths.allow  : `<access-letters> <absolute-prefix>`      e.g. `rw /home/user/workspace/k3/run`
 *   egress.allow : `<host> <port[,port]> [minIntervalMs=N] [maxRps=N]`
 *   tools.allow  : `<command> [argPattern ...]`
 */
export function parsePolicyLines(kind: "fs" | "net" | "command", text: string): AllowlistSpec {
	const fs: FsRule[] = [];
	const net: NetRule[] = [];
	const commands: CommandRule[] = [];
	const lines = text.split("\n");
	for (let i = 0; i < lines.length; i++) {
		const raw = lines[i].trim();
		if (raw.length === 0 || raw.startsWith("#")) continue;
		const parts = raw.split(/\s+/);
		if (kind === "fs") {
			const [modes, prefix] = parts;
			if (!modes || !prefix || !/^[rwx]+$/.test(modes)) {
				throw new Error(`paths.allow:${i + 1}: expected "<rwx> <prefix>", got ${JSON.stringify(raw)}`);
			}
			const access: FsAccess[] = [];
			if (modes.includes("r")) access.push("read");
			if (modes.includes("w")) access.push("write");
			if (modes.includes("x")) access.push("execute");
			fs.push({ prefix, access });
		} else if (kind === "net") {
			const [host, ports, ...rest] = parts;
			if (!host || !ports) {
				throw new Error(`egress.allow:${i + 1}: expected "<host> <ports>", got ${JSON.stringify(raw)}`);
			}
			const parsedPorts = ports.split(",").map((p) => Number.parseInt(p, 10));
			if (parsedPorts.some((p) => !Number.isInteger(p) || p <= 0 || p > 65535)) {
				throw new Error(`egress.allow:${i + 1}: invalid port list ${JSON.stringify(ports)}`);
			}
			const rule: { host: string; ports: number[]; minIntervalMs?: number; maxRps?: number } = {
				host,
				ports: parsedPorts,
			};
			for (const token of rest) {
				const [key, value] = token.split("=");
				const numeric = Number.parseInt(value ?? "", 10);
				if (!Number.isFinite(numeric)) {
					throw new Error(`egress.allow:${i + 1}: invalid qualifier ${JSON.stringify(token)}`);
				}
				if (key === "minIntervalMs") rule.minIntervalMs = numeric;
				else if (key === "maxRps") rule.maxRps = numeric;
				else throw new Error(`egress.allow:${i + 1}: unknown qualifier ${JSON.stringify(key)}`);
			}
			net.push(rule);
		} else {
			const [command, ...argPatterns] = parts;
			if (!command) throw new Error(`tools.allow:${i + 1}: empty command`);
			commands.push(argPatterns.length > 0 ? { command, argPatterns } : { command });
		}
	}
	return { version: "policy-file", fs, net, commands, denyRead: PROTECTED_DENY_READ, denyWrite: PROTECTED_DENY_WRITE };
}

/** Merges parsed policy fragments into one allowlist; missing fragments stay empty (default deny). */
export function composeAllowlist(version: string, fragments: readonly AllowlistSpec[]): Allowlist {
	return new Allowlist({
		version,
		fs: fragments.flatMap((f) => f.fs ?? []),
		net: fragments.flatMap((f) => f.net ?? []),
		commands: fragments.flatMap((f) => f.commands ?? []),
		denyRead: PROTECTED_DENY_READ,
		denyWrite: PROTECTED_DENY_WRITE,
	});
}

/**
 * K3 implant 路 W1-T1 路 Layer 2 domain proxy over `hostHandlers` (搂4.5.3).
 *
 * COMPONENT TRIPLE (verification_kernel.md 搂4.5.10)
 * - Reason to exist : the host_request surface needs semantic domain checks. Upstream
 *                     `agent-observe.ts` handler bodies contain no code-level permission check at
 *                     all (anchor A14) 鈥?the proxy supplies one.
 * - Axiom binding   : Axiom 5 (environment-layer enforcement). Carries G9's enforcement point.
 * - Deprecation     : NOT deprecable.
 *
 * PHYSICAL SINGLE POINTS (anchors A1 / A2)
 *   - construction : `agent-session.ts` `_createKernelHostHandlers()` 鈥?every handler gets wrapped.
 *   - dispatch     : `kernel/index.ts` `this.options.hostHandlers?.[data.type]` 鈥?the retrieved
 *                    handler is asserted to carry the `__k3_guarded` mark.
 * Wrapping at construction alone would let a "forgot to wrap" bug pass statically; asserting at
 * dispatch catches the same bug at RUNTIME. Both are required (搂4.5.3 triple hedge).
 *
 * DEFAULT DENY: `guardHandlers` wraps a handler only when a domain label exists for its type. Any
 * type without a declared label is replaced by a denying stub, so "undeclared" behaves exactly like
 * "forbidden" instead of "unrestricted".
 */

import type { HostRequestHandler, HostRequestHandlers } from "../../core/kernel/index.js";
import type { SecurityBoundary } from "./boundary.js";

/** The three K3 skill domains (three_domains.md 搂2). */
export type DomainName = "k3-research" | "k3-engineering" | "k3-ops" | "k3-kernel";

/** Capability classes a handler may declare. Mutation requires an explicit `mutate` capability. */
export type DomainCapability = "read" | "append" | "mutate" | "spawn" | "network";

export interface DomainSpec {
	readonly domain: DomainName;
	readonly capabilities: readonly DomainCapability[];
	/** Path prefixes this handler may touch; checked against the filesystem allowlist. */
	readonly pathPrefixes?: readonly string[];
	/** Hosts this handler may reach; requires the `network` capability. */
	readonly hosts?: readonly string[];
	/**
