/** Payload fields interpreted as filesystem paths that must clear the allowlist. */
const PATH_FIELDS = ["path", "file", "filePath", "target", "output", "outputPath", "dir"] as const;
/** Payload fields interpreted as network endpoints. */
const HOST_FIELDS = ["host", "url", "endpoint"] as const;

function extractHost(value: string): string | undefined {
	try {
		return new URL(value).hostname;
	} catch {
		return /^[a-z0-9.-]+$/i.test(value) ? value : undefined;
	}
}

function validateSpec(type: string, spec: DomainSpec): void {
	if (spec.readOnly && spec.capabilities.some((c) => c === "mutate" || c === "append")) {
		throw new DomainGuardError(
			`domain spec for "${type}" claims read-only but declares a write capability`,
			type,
			"readonly_contradiction",
		);
	}
	if (spec.hosts && spec.hosts.length > 0 && !spec.capabilities.includes("network")) {
		throw new DomainGuardError(
			`domain spec for "${type}" lists hosts without the "network" capability`,
			type,
			"host_without_network_capability",
		);
	}
	if (spec.capabilities.length === 0) {
		throw new DomainGuardError(`domain spec for "${type}" declares no capability`, type, "empty_capability_set");
	}
}

/**
 * Wraps one handler with domain enforcement. Every call:
 *   1. records a `domain.call` ledger event (audit trail for the host_request surface);
 *   2. checks declared capabilities against the payload shape;
 *   3. runs each path-like payload field through the filesystem allowlist;
 *   4. runs each host-like payload field through the egress allowlist;
 *   5. on any violation records `domain.deny` and throws 鈥?the request never reaches the handler.
 */
export function withDomainGuard(
	type: string,
	handler: HostRequestHandler,
	spec: DomainSpec,
	boundary: SecurityBoundary,
): GuardedHandler {
	validateSpec(type, spec);
	const guarded = (async (payload: Record<string, unknown>) => {
		boundary.record("domain.call", { type, domain: spec.domain, capabilities: spec.capabilities });

		const denies = (reason: string, subject: string): never => {
			boundary.record("domain.deny", { type, domain: spec.domain, reason, subject, verdict: "FAIL-KILL" });
			throw new DomainGuardError(`domain guard denied "${type}": ${reason} (${subject})`, type, reason);
		};

		// Read-only handlers may not receive mutation-shaped payloads.
		if (spec.readOnly && (payload.write === true || payload.mutate === true || typeof payload.content === "string")) {
			denies("mutation_payload_to_readonly_handler", type);
		}

		for (const field of PATH_FIELDS) {
			const value = payload[field];
			if (typeof value !== "string" || value.length === 0) continue;
			const access = spec.capabilities.includes("mutate") || spec.capabilities.includes("append") ? "write" : "read";
			if (spec.pathPrefixes && spec.pathPrefixes.length > 0) {
				const withinDeclared = spec.pathPrefixes.some((prefix) => value.includes(prefix));
				if (!withinDeclared) denies("path_outside_declared_domain_prefixes", value);
			}
			// Throws SecurityBoundaryError (and emits security.deny) when the path is not allowlisted.
			boundary.assertPath(value, access);
		}

		for (const field of HOST_FIELDS) {
			const value = payload[field];
			if (typeof value !== "string" || value.length === 0) continue;
			if (!spec.capabilities.includes("network")) denies("network_access_without_capability", value);
			const host = extractHost(value);
			if (!host) denies("unparseable_endpoint", value);
			if (spec.hosts && spec.hosts.length > 0 && !spec.hosts.includes(host as string)) {
				denies("host_outside_declared_domain_hosts", host as string);
			}
			const port = value.startsWith("http://") ? 80 : 443;
			boundary.assertEndpoint(host as string, port);
		}

		return handler(payload);
	}) as GuardedHandler;

	Object.defineProperties(guarded, {
		[GUARD_MARK]: { value: true, enumerable: false, writable: false, configurable: false },
		__k3_domain: { value: spec.domain, enumerable: false, writable: false, configurable: false },
		__k3_capabilities: {
			value: Object.freeze([...spec.capabilities]),
			enumerable: false,
			writable: false,
			configurable: false,
		},
	});
	return guarded;
}

/** True when the handler carries the proxy mark. Used by the dispatch-point runtime assertion. */
export function isGuardedHandler(handler: unknown): handler is GuardedHandler {
	return typeof handler === "function" && (handler as unknown as Record<string, unknown>)[GUARD_MARK] === true;
}

/** A stub that denies every call. Used for types with no declared domain label. */
export function denyingHandler(type: string, boundary: SecurityBoundary): GuardedHandler {
	const stub = (async () => {
		boundary.record("domain.deny", { type, reason: "no_domain_label_declared", verdict: "FAIL-KILL" });
		throw new DomainGuardError(
			`host_request type "${type}" has no declared domain label; default-deny applies`,
			type,
			"no_domain_label_declared",
		);
	}) as unknown as GuardedHandler;
	Object.defineProperties(stub, {
		[GUARD_MARK]: { value: true, enumerable: false, writable: false, configurable: false },
		__k3_domain: { value: "k3-kernel", enumerable: false, writable: false, configurable: false },
		__k3_capabilities: { value: Object.freeze([]), enumerable: false, writable: false, configurable: false },
	});
	return stub;
}

/**
 * Wraps a whole dispatch table (attachment point A2). Types without a domain label become denying
 * stubs rather than being passed through 鈥?declaration is mandatory, not advisory.
 */
export function guardHandlers(
	handlers: HostRequestHandlers,
	boundary: SecurityBoundary,
	registry: Readonly<Record<string, DomainSpec>> = DOMAIN_REGISTRY,
): { handlers: HostRequestHandlers; guarded: string[]; denied: string[] } {
	const out: HostRequestHandlers = {};
	const guarded: string[] = [];
	const denied: string[] = [];
	for (const [type, handler] of Object.entries(handlers)) {
		const spec = registry[type];
		if (!spec) {
			out[type] = denyingHandler(type, boundary);
			denied.push(type);
			continue;
		}
		out[type] = withDomainGuard(type, handler, spec, boundary);
		guarded.push(type);
	}
	return { handlers: out, guarded, denied };
}

/**
 * Dispatch-point assertion (attachment point A1). Call this with whatever the dispatch table
 * returned, before invoking it: an unwrapped handler is a registration bug and must fail loudly at
 * runtime, not only in a static assertion.
 */
export function assertGuardedAtDispatch(type: string, handler: unknown): GuardedHandler {
	if (!isGuardedHandler(handler)) {
		throw new DomainGuardError(
			`host_request handler for "${type}" is not domain-guarded (missing ${GUARD_MARK}); refusing to dispatch`,
			type,
			"unguarded_handler_at_dispatch",
		);
	}
	return handler;
}

