import { canonicalizePath } from "../../utils/paths.js";

/** Tri-state trust decision, matching pi's `ProjectTrustDecision`. */
export type TrustDecision = boolean | null;

export interface TrustEntry {
	readonly path: string;
	readonly decision: boolean;
}

/**
 * Resources whose loading requires trust. Ported verbatim from pi's
 * `TRUST_REQUIRING_PROJECT_CONFIG_RESOURCES`, extended with the K3 policy surfaces.
 */
export const TRUST_REQUIRING_RESOURCES: readonly string[] = [
	"settings.json",
	"extensions",
	"skills",
	"prompts",
	"themes",
	"SYSTEM.md",
	"APPEND_SYSTEM.md",
	// K3 additions: anything that can change what the boundary enforces.
	"policy",
	"gates",
];

function normalize(path: string): string {
	return canonicalizePath(resolve(path));
}

/**
 * Nearest-ancestor trust lookup (pi `findNearestTrustEntry`, ported).
 * Walks upward from `cwd`; the first explicit true/false wins. No entry => `null`,
 * which the K3 resolver treats as DENY (pi treated it as "ask the user").
 */
export function findNearestTrustEntry(store: Readonly<Record<string, TrustDecision>>, cwd: string): TrustEntry | null {
	let current = normalize(cwd);
	for (;;) {
		const value = store[current];
		if (value === true || value === false) return { path: current, decision: value };
		const parent = dirname(current);
		if (parent === current) return null;
		current = parent;
	}
}

export interface DomainTrustInput {
	readonly cwd: string;
	readonly store: Readonly<Record<string, TrustDecision>>;
	/** Emitted when the resolver falls through to the unattended default. */
	readonly onDeny?: (reason: string) => void;
}

export interface DomainTrustResult {
	readonly trusted: boolean;
	readonly reason: string;
	readonly matchedPath?: string;
	/** True when the caller must transition the run to HOLD rather than continue. */
	readonly hold: boolean;
