 *  - no `trustOverride` parameter        (switch removed from the config surface);
 *  - no `defaultProjectTrust` parameter  (the default is hardcoded to the strictest rung);
 *  - no UI prompt path                   (unattended runs cannot answer a prompt, and a prompt
 *                                         that times out into "allow" is the classic failure);
 *  - no extension consultation           (extensions are removable, В§5.2).
 */
export function resolveDomainTrust(input: DomainTrustInput): DomainTrustResult {
	const entry = findNearestTrustEntry(input.store, input.cwd);
	if (entry === null) {
		input.onDeny?.("no_trust_entry");
		return { trusted: false, reason: "no_trust_entry", hold: true };
	}
	if (!entry.decision) {
		input.onDeny?.("explicit_distrust");
		return { trusted: false, reason: "explicit_distrust", matchedPath: entry.path, hold: true };
	}
	return { trusted: true, reason: "nearest_ancestor_trusted", matchedPath: entry.path, hold: false };
}

