import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { LedgerSink } from "./boundary.js";

const execFileAsync = promisify(execFile);

/** Minimal git runner seam so tests can drive the state machine without a real repo. */
export type GitRunner = (args: readonly string[]) => Promise<{ stdout: string; stderr: string }>;

/** Commands this module is ever allowed to run. Anything else is a programming error. */
const ALLOWED_GIT_SUBCOMMANDS = new Set([
	"rev-parse",
	"status",
	"stash",
	"diff",
	"worktree",
	"add",
	"commit",
	"checkout",
	"restore",
	"rev-list",
	"log",
]);

/** Argument forms banned by the upstream AGENTS.md discipline (搂4.5.8 last row). */
const BANNED_ARG_SEQUENCES: readonly (readonly string[])[] = [
	["add", "-A"],
	["add", "--all"],
	["add", "."],
	["reset", "--hard"],
	["push", "--force"],
	["push", "-f"],
];

export class GitDisciplineError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "GitDisciplineError";
	}
}

export class RollbackFailedError extends Error {
	constructor(
		message: string,
		readonly snapshot: SnapshotHandle,
		readonly cause?: unknown,
	) {
		super(message);
		this.name = "RollbackFailedError";
	}
}

export function assertGitDiscipline(args: readonly string[]): void {
	const sub = args[0];
	if (sub === undefined || !ALLOWED_GIT_SUBCOMMANDS.has(sub)) {
		throw new GitDisciplineError(`git subcommand "${String(sub)}" is not in the K3 allowlist`);
	}
	for (const banned of BANNED_ARG_SEQUENCES) {
		if (banned.every((token, index) => args[index] === token)) {
			throw new GitDisciplineError(`git ${banned.join(" ")} is forbidden by the K3 / upstream AGENTS.md discipline`);
		}
	}
}

export function createGitRunner(cwd: string): GitRunner {
	return async (args) => {
		assertGitDiscipline(args);
		const { stdout, stderr } = await execFileAsync("git", [...args], { cwd, maxBuffer: 16 * 1024 * 1024 });
		return { stdout, stderr };
	};
