	readonly rollbackRehearsed?: boolean;
}

/**
 * Snapshot/rollback state machine.
 *
 * `guard()` is the intended entry point: it snapshots, runs the mutation, and rolls back on any
 * failure 鈥?including a security-boundary denial 鈥?so no caller can forget the rollback branch.
 */
export class GitSnapshotManager {
	private readonly git: GitRunner;
	private readonly ledger: LedgerSink;
	private readonly subjects: SnapshotSubjects;
	private readonly rehearsed: boolean;
	private seq = 0;
	private readonly live = new Map<number, SnapshotHandle>();

	constructor(options: SnapshotManagerOptions) {
		this.git = options.git;
		this.ledger = options.ledger ?? (() => {});
		this.subjects = options.subjects ?? FULL_SNAPSHOT_SUBJECTS;
		this.rehearsed = options.rollbackRehearsed ?? false;
	}

	private emit(type: Parameters<LedgerSink>[0]["type"], detail: Record<string, unknown>): void {
		this.ledger({ type, ts: new Date().toISOString(), detail });
	}

	/** Records the rehearsal event 搂4.5.8 requires before a rollback path may be relied on. */
	async rehearseRollback(): Promise<void> {
		const head = (await this.git(["rev-parse", "HEAD"])).stdout.trim();
		this.emit("rollback.verify", { head, rehearsed: true, note: "rollback path exercised before first use" });
	}

	/**
	 * Captures the pre-change state. Throws when any required subject is missing or when the
	 * rollback path has not been rehearsed 鈥?"snapshot failure => the change must not proceed".
	 */
	async createSnapshot(label: string): Promise<SnapshotHandle> {
		if (!this.rehearsed) {
			throw new RollbackFailedError(
				"refusing to snapshot: rollback path not rehearsed (搂4.5.8 requires a rollback.verify event first)",
				{
					ledgerSeq: -1,
					label,
					head: "",
					createdAt: new Date().toISOString(),
					subjects: this.subjects,
					rehearsed: false,
				},
			);
		}
		const missing = Object.entries(this.subjects)
			.filter(([, captured]) => !captured)
			.map(([name]) => name);
		if (missing.length > 0) {
			throw new GitDisciplineError(
				`snapshot would be incomplete: subjects not captured => ${missing.join(", ")} (搂4.5.8 row 1)`,
			);
		}

		const seq = ++this.seq;
		const head = (await this.git(["rev-parse", "HEAD"])).stdout.trim();
		const status = (await this.git(["status", "--porcelain"])).stdout;
		let stashRef: string | undefined;
		if (status.trim().length > 0) {
			// `stash push --include-untracked` keeps the tree recoverable without `git add -A`.
			await this.git(["stash", "push", "--include-untracked", "-m", `k3-snapshot ledger_seq:${seq} ${label}`]);
			stashRef = (await this.git(["rev-parse", "refs/stash"])).stdout.trim();
		}
		const handle: SnapshotHandle = {
			ledgerSeq: seq,
			label,
			head,
			stashRef,
			createdAt: new Date().toISOString(),
			subjects: this.subjects,
			rehearsed: true,
		};
		this.live.set(seq, handle);
		this.emit("snapshot.created", {
			ledger_seq: seq,
			label,
			head,
			stashRef: stashRef ?? null,
			dirtyTree: stashRef !== undefined,
			subjects: this.subjects,
		});
		return handle;
	}

	/**
	 * Restores the snapshot. On any failure this throws `RollbackFailedError` and emits
	 * `rollback.failed`; it never returns a "partially rolled back" success.
	 */
	async rollback(handle: SnapshotHandle, reason: string): Promise<void> {
		try {
			// Tracked-file reset without `reset --hard`: restore the worktree from the snapshot commit.
			await this.git(["checkout", "--", "."]);
			if (handle.stashRef) {
				await this.git(["stash", "pop", handle.stashRef]);
			}
			const head = (await this.git(["rev-parse", "HEAD"])).stdout.trim();
			if (head !== handle.head) {
				throw new Error(`HEAD is ${head}, expected ${handle.head} after rollback`);
			}
			this.live.delete(handle.ledgerSeq);
			this.emit("rollback.pointer_move", {
				ledger_seq: handle.ledgerSeq,
				label: handle.label,
				head: handle.head,
				reason,
				restoredStash: handle.stashRef ?? null,
				complete: true,
			});
		} catch (error) {
			this.emit("rollback.failed", {
				ledger_seq: handle.ledgerSeq,
				label: handle.label,
				head: handle.head,
				reason,
				error: error instanceof Error ? error.message : String(error),
				loud: true,
			});
			throw new RollbackFailedError(
				`rollback of snapshot ledger_seq:${handle.ledgerSeq} FAILED and must not be treated as partial success: ${
					error instanceof Error ? error.message : String(error)
				}`,
				handle,
				error,
			);
		}
	}

	/** Marks a snapshot as accepted; the commit message carries `ledger_seq` for two-way alignment. */
	async commitSnapshot(handle: SnapshotHandle, message: string, paths: readonly string[]): Promise<void> {
		if (paths.length === 0)
			throw new GitDisciplineError("commitSnapshot requires explicit paths (never `git add -A`)");
		await this.git(["add", "--", ...paths]);
		await this.git(["commit", "-m", `${message}\n\nledger_seq:${handle.ledgerSeq}`]);
		this.live.delete(handle.ledgerSeq);
	}

	get liveSnapshotCount(): number {
		return this.live.size;
	}

	/**
	 * Snapshot 鈫?run 鈫?rollback-on-failure. This is the wrapper tool execution must go through:
	 * a boundary denial or any thrown error triggers the rollback, and the rollback outcome is
	 * always in the ledger.
	 */
	async guard<T>(label: string, fn: (handle: SnapshotHandle) => Promise<T>): Promise<T> {
		const handle = await this.createSnapshot(label);
		try {
			return await fn(handle);
		} catch (error) {
			await this.rollback(handle, error instanceof Error ? error.message : String(error));
			throw error;
		}
	}

	/** Creates a per-candidate worktree (file isolation; must be stacked with a runtime sandbox). */
	async createCandidateWorktree(path: string, commitish: string): Promise<void> {
		await this.git(["worktree", "add", "--detach", path, commitish]);
		this.emit("snapshot.created", {
			worktree: path,
			commitish,
			note: "file isolation only 鈥?stack a runtime sandbox",
		});
	}
}

/**
 * K3 implant · W1-T1 · dispatch-point runtime assertion (§4.5.3, anchor A1).
 *
 * COMPONENT TRIPLE (verification_kernel.md §4.5.10)
 * - Reason to exist : wrapping at the construction point (A2) alone lets a "forgot to wrap" bug
 *                     pass silently; the dispatch point is where that bug becomes observable at
 *                     runtime. §4.5.3 requires BOTH.
 * - Axiom binding   : Axiom 5 (environment-layer enforcement). Hedge 2 of 3 for the single-point
 *                     risk of the hostHandlers dispatch table.
 * - Deprecation     : NOT deprecable while the domain proxy exists.
 *
 * WHY IT IS ARMED RATHER THAN ALWAYS-ON
 * K3 implants must be independently removable, and while the boundary is not installed the Prime
 * main loop must behave exactly as upstream. So the check is a no-op until `armDispatchAssertion()`
 * runs, which only `installK3SecurityBoundary()` does. Once armed there is no disarm path reachable
 * from the agent domain: `disarmDispatchAssertion` is exported for test teardown only and is itself
 * outside the kernel process's reach (it lives in the harness-side Node module graph, not in the
 * kernel's Python namespace, so no model-generated code can call it).
 */

import { GUARD_MARK } from "./domain-guard.js";

let armed = false;
let onViolation: ((type: string) => void) | undefined;

/** Turns the dispatch assertion on. Called by `installK3SecurityBoundary`. */
export function armDispatchAssertion(handler?: (type: string) => void): void {
	armed = true;
	onViolation = handler;
}

/** Test-teardown seam. Not reachable from the kernel process. */
export function disarmDispatchAssertion(): void {
	armed = false;
	onViolation = undefined;
}

export function isDispatchAssertionArmed(): boolean {
	return armed;
}

/**
 * Asserts the handler retrieved at the dispatch point carries the domain-proxy mark.
 * Inert (returns immediately) until armed, so removing the K3 implant restores upstream behaviour
 * with the single call site left in place doing nothing.
 */
export function assertDispatchGuarded(type: string, handler: unknown): void {
	if (!armed) return;
	const marked = typeof handler === "function" && (handler as unknown as Record<string, unknown>)[GUARD_MARK] === true;
	if (marked) return;
	onViolation?.(type);
	throw new Error(
		`K3 security boundary: host_request handler "${type}" is not domain-guarded (missing ${GUARD_MARK}); refusing to dispatch`,
	);
}

/**
 * K3 implant · W1-T1 · security boundary guard tests.
 *
 * Covers the acceptance canaries named in axiom7_enumeration.md Decision 1 and
 * verification_kernel.md §4.5.4 (read `~/.ssh`, reach a non-allowlisted host, write `.env`),
 * plus the default-deny path policy, git snapshot rollback, resource limits, the domain proxy,
 * and allowlist configurability.
 */

import { mkdtempSync, rmSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { beforeEach, describe, expect, it } from "vitest";
import {
