import { findNearestTrustEntry, resolveDomainTrust } from "../src/k3/security/trust.js";

const REPO_ROOT = "/tmp/k3-test-repo";

function makeAllowlist(): Allowlist {
	return new Allowlist({
		version: "test-v1",
		fs: [
			{ prefix: `${REPO_ROOT}/work`, access: ["read", "write"] },
			{ prefix: `${REPO_ROOT}/readonly`, access: ["read"] },
		],
		net: [
			{ host: "export.arxiv.org", ports: [443] },
			{ host: "*.openalex.org", ports: [443], maxRps: 10 },
		],
		commands: [
			{ command: "git", argPatterns: ["^[a-z-]+$", "^--?[a-z-]+$", "^[A-Za-z0-9._/-]+$"] },
			{ command: "node" },
		],
		denyRead: PROTECTED_DENY_READ,
		denyWrite: PROTECTED_DENY_WRITE,
	});
