function makeBoundary(): { boundary: SecurityBoundary; events: ReturnType<typeof createMemoryLedger>["events"] } {
	const { sink, events } = createMemoryLedger();
	const boundary = new SecurityBoundary({ allowlist: makeAllowlist(), ledger: sink, repoRoot: REPO_ROOT });
	return { boundary, events };
}

describe("K3 security boundary · default-deny path policy (§4.5.4)", () => {
	it("denies a path that is not in the filesystem allowlist", () => {
		const { boundary, events } = makeBoundary();
		expect(() => boundary.assertPath("/etc/shadow", "read")).toThrow(SecurityBoundaryError);
		const deny = events.find((e) => e.type === "security.deny");
		expect(deny?.detail.reason).toBe("not_in_allowlist");
		expect(deny?.detail.verdict).toBe("FAIL-KILL");
	});

	it("allows a path that is positively listed for the requested access mode", () => {
		const { boundary } = makeBoundary();
		expect(() => boundary.assertPath(`${REPO_ROOT}/work/candidate.py`, "write")).not.toThrow();
		expect(() => boundary.assertPath(`${REPO_ROOT}/readonly/spec.md`, "read")).not.toThrow();
	});

	it("denies write to a read-only prefix even though the prefix is listed", () => {
		const { boundary } = makeBoundary();
		expect(() => boundary.assertPath(`${REPO_ROOT}/readonly/spec.md`, "write")).toThrow(/not_in_allowlist/);
	});

	it("matches prefixes on path boundaries, so /a/b never covers /a/bc", () => {
		expect(pathHasPrefix("/a/b/c", "/a/b")).toBe(true);
		expect(pathHasPrefix("/a/b", "/a/b")).toBe(true);
		expect(pathHasPrefix("/a/bc", "/a/b")).toBe(false);
		const { boundary } = makeBoundary();
		expect(() => boundary.assertPath(`${REPO_ROOT}/workshop/x`, "read")).toThrow(SecurityBoundaryError);
	});

	it("acceptance canary 1: reading ~/.ssh is blocked and ledgered", () => {
		const { boundary, events } = makeBoundary();
		expect(() => boundary.assertPath(join(homedir(), ".ssh", "id_ed25519"), "read")).toThrow(SecurityBoundaryError);
		expect(events.filter((e) => e.type === "security.deny")).toHaveLength(1);
	});

	it("acceptance canary 2: connecting to a non-allowlisted host is blocked and ledgered", () => {
		const { boundary, events } = makeBoundary();
		expect(() => boundary.assertEndpoint("evil.example.com", 443)).toThrow(SecurityBoundaryError);
		expect(() => boundary.assertEndpoint("export.arxiv.org", 443)).not.toThrow();
		// listed host on an unlisted port is still denied
		expect(() => boundary.assertEndpoint("export.arxiv.org", 8080)).toThrow(/port_not_in_allowlist/);
		expect(events.filter((e) => e.type === "security.deny")).toHaveLength(2);
	});

	it("acceptance canary 3: writing .env is blocked and ledgered", () => {
		const { boundary, events } = makeBoundary();
		expect(() => boundary.assertPath(join(homedir(), ".env"), "write")).toThrow(SecurityBoundaryError);
		expect(events.at(-1)?.detail.verdict).toBe("FAIL-KILL");
	});

	it("protected prefixes win over allow rules and cannot be re-opened (§4.5.6)", () => {
		const permissive = new Allowlist({
			version: "attempted-reopen",
			fs: [{ prefix: "k3", access: ["read", "write"] }],
			denyRead: PROTECTED_DENY_READ,
			denyWrite: PROTECTED_DENY_WRITE,
		});
		expect(permissive.checkPath("k3/ledger/main.jsonl", "write").reason).toBe("protected_prefix");
		expect(permissive.checkPath("k3/policy/paths.allow", "write").reason).toBe("protected_prefix");
		expect(permissive.checkPath("k3/canary/corpus.jsonl", "read").reason).toBe("protected_prefix");
		expect(permissive.checkPath("k3/eval/sealed/holdout.jsonl", "read").reason).toBe("protected_prefix");
	});

	it("starts at zero privilege: the empty allowlist denies everything", () => {
		const empty = emptyAllowlist();
		expect(empty.checkPath("/tmp/anything", "read").allowed).toBe(false);
		expect(empty.checkEndpoint("example.com", 443).allowed).toBe(false);
		expect(empty.checkCommand("ls").allowed).toBe(false);
	});

	it("denies commands outside the tool allowlist and arguments outside the pattern set", () => {
		const { boundary } = makeBoundary();
		expect(() => boundary.assertCommand("curl", ["https://evil.example.com"])).toThrow(/not_in_allowlist/);
		expect(() => boundary.assertCommand("git", ["status"])).not.toThrow();
		expect(() => boundary.assertCommand("git", ["commit", "-m", "hello world; rm -rf /"])).toThrow(
			/argument_not_allowed/,
		);
	});
});

describe("K3 security boundary · allowlist configurability (§4.5.4)", () => {
