describe("K3 security boundary · git snapshot rollback (§4.5.8)", () => {
	interface FakeGit {
		runner: GitRunner;
		calls: string[][];
		dirty: boolean;
		head: string;
		failOn?: string;
	}

	function fakeGit(overrides: Partial<Pick<FakeGit, "dirty" | "head" | "failOn">> = {}): FakeGit {
		const state: FakeGit = {
			calls: [],
			dirty: overrides.dirty ?? true,
			head: overrides.head ?? "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
			failOn: overrides.failOn,
			runner: async () => ({ stdout: "", stderr: "" }),
		};
		state.runner = async (args) => {
			assertGitDiscipline(args);
			state.calls.push([...args]);
			if (state.failOn && args.join(" ").startsWith(state.failOn)) {
				throw new Error(`simulated git failure on: ${args.join(" ")}`);
			}
			if (args[0] === "rev-parse" && args[1] === "HEAD") return { stdout: `${state.head}\n`, stderr: "" };
			if (args[0] === "rev-parse" && args[1] === "refs/stash") return { stdout: "stash@{0}\n", stderr: "" };
			if (args[0] === "status") return { stdout: state.dirty ? " M src/foo.ts\n" : "", stderr: "" };
			return { stdout: "", stderr: "" };
		};
		return state;
	}

	it("refuses to snapshot before the rollback path has been rehearsed", async () => {
		const git = fakeGit();
		const mgr = new GitSnapshotManager({ git: git.runner, rollbackRehearsed: false });
		await expect(mgr.createSnapshot("t")).rejects.toThrow(/not rehearsed/);
	});

	it("snapshots before the change and stamps ledger_seq into the stash message", async () => {
		const git = fakeGit();
		const { sink, events } = createMemoryLedger();
		const mgr = new GitSnapshotManager({ git: git.runner, ledger: sink, rollbackRehearsed: true });
		const handle = await mgr.createSnapshot("tool-exec");
		expect(handle.ledgerSeq).toBe(1);
		expect(handle.stashRef).toBe("stash@{0}");
		const stashCall = git.calls.find((c) => c[0] === "stash");
		expect(stashCall?.join(" ")).toContain("ledger_seq:1");
		expect(events.find((e) => e.type === "snapshot.created")?.detail.ledger_seq).toBe(1);
	});

	it("refuses to snapshot when a behaviour-determining subject cannot be captured", async () => {
		const git = fakeGit();
		const mgr = new GitSnapshotManager({
			git: git.runner,
			rollbackRehearsed: true,
			subjects: {
				code: true,
				prompts: true,
				toolManifest: true,
				modelIdentity: true,
				memory: true,
				schema: true,
				allowlists: false, // the three allowlists are part of the snapshot subject set
				gateTable: true,
			},
		});
		await expect(mgr.createSnapshot("t")).rejects.toThrow(/allowlists/);
	});

	it("rolls back automatically when the guarded tool execution fails", async () => {
		const git = fakeGit();
		const { sink, events } = createMemoryLedger();
		const mgr = new GitSnapshotManager({ git: git.runner, ledger: sink, rollbackRehearsed: true });
		await expect(
			mgr.guard("failing-tool", async () => {
				throw new Error("tool blew up");
			}),
		).rejects.toThrow("tool blew up");
		const rollback = events.find((e) => e.type === "rollback.pointer_move");
		expect(rollback?.detail.complete).toBe(true);
		expect(rollback?.detail.reason).toBe("tool blew up");
		expect(mgr.liveSnapshotCount).toBe(0);
	});

	it("rolls back when the tool execution violates the security boundary", async () => {
		const git = fakeGit();
		const { sink, events } = createMemoryLedger();
		const boundary = new SecurityBoundary({ allowlist: makeAllowlist(), ledger: sink, repoRoot: REPO_ROOT });
		const mgr = new GitSnapshotManager({ git: git.runner, ledger: sink, rollbackRehearsed: true });
		await expect(
			mgr.guard("boundary-violating-tool", async () => {
				boundary.assertPath("/etc/shadow", "read");
			}),
		).rejects.toThrow(SecurityBoundaryError);
		expect(events.some((e) => e.type === "security.deny")).toBe(true);
		expect(events.some((e) => e.type === "rollback.pointer_move")).toBe(true);
	});

	it("keeps the result when the guarded execution succeeds and leaves no dangling snapshot", async () => {
		const git = fakeGit({ dirty: false });
		const mgr = new GitSnapshotManager({ git: git.runner, rollbackRehearsed: true });
		await expect(mgr.guard("ok-tool", async () => "value")).resolves.toBe("value");
	});

	it("fails loudly when the rollback itself fails, never degrading to a partial success", async () => {
		const git = fakeGit({ failOn: "stash pop" });
		const { sink, events } = createMemoryLedger();
		const mgr = new GitSnapshotManager({ git: git.runner, ledger: sink, rollbackRehearsed: true });
		const handle = await mgr.createSnapshot("t");
		await expect(mgr.rollback(handle, "test")).rejects.toBeInstanceOf(RollbackFailedError);
		const failed = events.find((e) => e.type === "rollback.failed");
		expect(failed?.detail.loud).toBe(true);
	});

	it("enforces the upstream AGENTS.md git discipline", () => {
		expect(() => assertGitDiscipline(["add", "-A"])).toThrow(GitDisciplineError);
		expect(() => assertGitDiscipline(["add", "."])).toThrow(GitDisciplineError);
		expect(() => assertGitDiscipline(["reset", "--hard"])).toThrow(GitDisciplineError);
		expect(() => assertGitDiscipline(["push", "--force"])).toThrow(GitDisciplineError);
		expect(() => assertGitDiscipline(["add", "--", "src/foo.ts"])).not.toThrow();
	});

	it("records a rollback.verify rehearsal event", async () => {
		const git = fakeGit();
		const { sink, events } = createMemoryLedger();
		const mgr = new GitSnapshotManager({ git: git.runner, ledger: sink, rollbackRehearsed: true });
		await mgr.rehearseRollback();
		expect(events.find((e) => e.type === "rollback.verify")?.detail.rehearsed).toBe(true);
	});
});

