const HARNESS = { role: "harness" } as const;
const PHASE = "W3";

let root: string;
let ledgerDir: string;
let ledger: EventLedger;

beforeEach(() => {
	root = mkdtempSync(join(tmpdir(), "k3-gate-"));
	ledgerDir = join(root, "k3", "ledger");
	mkdirSync(ledgerDir, { recursive: true });
	ledger = new EventLedger({ dir: ledgerDir });
});

afterEach(() => {
	ledger.close();
	rmSync(root, { recursive: true, force: true });
});

function effort(eventType: string, payload: Record<string, unknown>, phase = PHASE): void {
	ledger.append({ event_type: eventType, actor: HARNESS, action: "record", phase, payload });
}

function baseCtx(overrides: Partial<L1Context> = {}): L1Context {
	return { ledgerDir, phase: PHASE, floors: DEFAULT_EXTENSIVE_FLOORS, ...overrides };
}

/** Seeds the ledger so that every predicate in ALL_L1_PREDICATES passes with baseCtx + extras. */
function seedCleanPhase(): { deliverable: string; verifyArtifact: string } {
	for (let i = 0; i < DEFAULT_EXTENSIVE_FLOORS.retrievalMin; i++) effort("effort.retrieval", { query: `q${i}` });
	for (let i = 0; i < DEFAULT_EXTENSIVE_FLOORS.fulltextNotesMin; i++)
		effort("effort.reading_note", { depth: "fulltext", note: `n${i}` });
	effort("effort.alternative", { decision_id: "D1", option: "A" });
	effort("effort.alternative", { decision_id: "D1", option: "B" });
	effort("effort.verifier_run", { tier: "L1", exit: 0 });
	const deliverable = join(root, "deliverable.md");
	writeFileSync(deliverable, "---\ntitle: x\n---\nbody\n");
	const verifyArtifact = join(root, "verify.log");
	writeFileSync(verifyArtifact, "all green\nEXIT=0\n");
	return { deliverable, verifyArtifact };
}

// ---------------------------------------------------------------------------
// Family 1 路 P1鈥揚9 (intensive-vs-extensive floor discipline)
// ---------------------------------------------------------------------------

describe("L1 family 1 鈥?no-LLM counting predicates (P1鈥揚9)", () => {
	it("P1 holds below the retrieval floor and passes at it (extensive floor from admission contract)", () => {
		effort("effort.retrieval", { query: "a" });
		const under = p1RetrievalFloor(baseCtx());
		expect(under.ok).toBe(false);
		expect(under.verdict_on_fail).toBe("HOLD"); // unevaluable, NOT a failure
		expect(under.provisional).toBe(true); // PROVISIONAL: 寰?GAP-058 鏍囧畾
		effort("effort.retrieval", { query: "b" });
		effort("effort.retrieval", { query: "c" });
		expect(p1RetrievalFloor(baseCtx()).ok).toBe(true);
	});

	it("P1 counts only the phase under judgment (ledger query, not global count)", () => {
		for (let i = 0; i < 5; i++) effort("effort.retrieval", { query: `other${i}` }, "W2");
		expect(p1RetrievalFloor(baseCtx()).ok).toBe(false);
	});

	it("P2 counts fulltext notes only 鈥?depth types never substitute (搂4.2.6 quality typing)", () => {
		effort("effort.reading_note", { depth: "summary" });
		effort("effort.reading_note", { depth: "summary" });
		effort("effort.reading_note", { depth: "summary" });
		const r = p2FulltextNotesFloor(baseCtx());
		expect(r.ok).toBe(false); // 3 summaries do not equal 2 fulltext reads
		effort("effort.reading_note", { depth: "fulltext" });
		effort("effort.reading_note", { depth: "fulltext" });
		expect(p2FulltextNotesFloor(baseCtx()).ok).toBe(true);

	});

	it("P3 recycles any decision with fewer than 2 competing alternatives (Axiom 7 mechanized)", () => {
		effort("effort.alternative", { decision_id: "D1", option: "only-one" });
		const r = p3EnumerationFloor(baseCtx({ decisionIds: ["D1"] }));
		expect(r.ok).toBe(false);
		expect(r.verdict_on_fail).toBe("RECYCLE");
		expect(r.provisional).toBe(false); // structural, not a tunable
		effort("effort.alternative", { decision_id: "D1", option: "two" });
		expect(p3EnumerationFloor(baseCtx({ decisionIds: ["D1"] })).ok).toBe(true);
	});

	it("P3 catches decisions declared in the contract but absent from the ledger entirely", () => {
		const r = p3EnumerationFloor(baseCtx({ decisionIds: ["D-ghost"] }));
		expect(r.ok).toBe(false);
		expect(r.detail).toContain("D-ghost");
	});

	it("P4 FAIL-KILLs when no L1 verifier ran, and when any run exited non-zero", () => {
		const missing = p4VerifierRuns(baseCtx());
		expect(missing.ok).toBe(false);
		expect(missing.verdict_on_fail).toBe("FAIL-KILL");
		effort("effort.verifier_run", { tier: "L1", exit: 1 });
		expect(p4VerifierRuns(baseCtx()).ok).toBe(false);
		effort("effort.verifier_run", { tier: "L1", exit: 0 });
