// Four-valued verdicts, severity folding, provisional discipline
// ---------------------------------------------------------------------------

describe("four-valued verdict (搂4.2.2) and L1 folding", () => {
	it("severity order is FAIL-KILL > RECYCLE > HOLD > PASS", () => {
		expect(VERDICT_SEVERITY["FAIL-KILL"]).toBeGreaterThan(VERDICT_SEVERITY.RECYCLE);
		expect(VERDICT_SEVERITY.RECYCLE).toBeGreaterThan(VERDICT_SEVERITY.HOLD);
		expect(VERDICT_SEVERITY.HOLD).toBeGreaterThan(VERDICT_SEVERITY.PASS);
	});

	it("all four verdicts are reachable and each decision lands as a gate.decision ledger row", async () => {
		const gate = new StageGate({ ledger, ledgerDir });
		// RECYCLE: enumeration floor violated.
		effort("effort.alternative", { decision_id: "D1", option: "only" });
		effort("effort.verifier_run", { tier: "L1", exit: 0 });
		for (let i = 0; i < 3; i++) effort("effort.retrieval", { q: i });
		effort("effort.reading_note", { depth: "fulltext" });
		effort("effort.reading_note", { depth: "fulltext" });
		const recycle = await gate.decide("phase.exit", baseCtx({ decisionIds: ["D1"] }));
		expect(recycle.verdict).toBe("RECYCLE");

		// HOLD: retrieval floor unmet in a fresh phase (unevaluable, provisional-advisory tier).
		const hold = await gate.decide(
			"phase.exit",
			baseCtx({
				phase: "W-empty",
				floors: { ...DEFAULT_EXTENSIVE_FLOORS, alternativesPerDecision: 0, verifierRunsMin: 0 },
			}),
		);
		expect(hold.verdict).toBe("HOLD");
		expect(hold.reason_codes).toContain("P1_RETRIEVAL_FLOOR_UNMET");

		// FAIL-KILL: boundary violation (critical) 鈥?also emits security.escalate.
		ledger.append({ event_type: "security.deny", actor: HARNESS, action: "deny", phase: "W-bad", payload: {} });
		const kill = await gate.decide("phase.exit", baseCtx({ phase: "W-bad" }));
		expect(kill.verdict).toBe("FAIL-KILL");

		// PASS: fully seeded phase.
		effort("effort.alternative", { decision_id: "D1", option: "second" });
		const { verifyArtifact } = seedCleanPhase();
		const pass = await gate.decide("phase.exit", baseCtx({ verifyArtifact }));
		expect(pass.verdict).toBe("PASS");

		const rows = [...scanLedger(ledgerDir, (r) => r.event_type === "gate.decision")];
		expect(rows.map((r) => (r.payload as { verdict: string }).verdict)).toEqual([
			"RECYCLE",
			"HOLD",
			"FAIL-KILL",
			"PASS",
		]);
		const escalations = [...scanLedger(ledgerDir, (r) => r.event_type === "security.escalate")];
		expect(escalations).toHaveLength(1);
	});

	it("HOLD carries a reason_code always (never a silent unevaluable)", async () => {
		const gate = new StageGate({ ledger, ledgerDir });
		effort("phase.enter", { phase: PHASE }); // ledger non-empty so Q3 is clean
		const hold = await gate.decide(
			"phase.exit",
			baseCtx({ floors: { ...DEFAULT_EXTENSIVE_FLOORS, alternativesPerDecision: 0, verifierRunsMin: 0 } }),
		);
		expect(hold.verdict).toBe("HOLD");
		expect(hold.reason_codes.length).toBeGreaterThan(0);
	});

	it("unattended runs fold HOLD 鈫?FAIL-KILL and the fold itself is ledgered (folded_from)", async () => {
		const gate = new StageGate({ ledger, ledgerDir, unattended: true });
		effort("phase.enter", { phase: PHASE }); // ledger non-empty so Q3 is clean
		const folded = await gate.decide(
			"phase.exit",
			baseCtx({ floors: { ...DEFAULT_EXTENSIVE_FLOORS, alternativesPerDecision: 0, verifierRunsMin: 0 } }),
		);
		expect(folded.verdict).toBe("FAIL-KILL");
		expect(folded.folded_from).toBe("HOLD");
		const row = [...scanLedger(ledgerDir, (r) => r.event_type === "gate.decision")].at(-1);
		expect((row?.payload as { folded_from: string }).folded_from).toBe("HOLD");
		// A folded kill is NOT a criteria kill: no security.escalate is emitted for it.
		expect([...scanLedger(ledgerDir, (r) => r.event_type === "security.escalate")]).toHaveLength(0);
	});

	it("a provisional threshold can never be the source of a FAIL-KILL (risk R4 hard assert)", () => {
		const rogue = () => ({
			id: "PX",
			check: "rogue provisional kill",
			ok: false,
			verdict_on_fail: "FAIL-KILL" as const,
			provisional: true,
			reason_code: "PX_ROGUE",
			detail: "uncalibrated threshold trying to kill",
		});
		expect(() => evaluateL1(baseCtx(), [rogue])).toThrow(ProvisionalThresholdError);
	});

	it("provisional violations are annotated as advisory in the evaluation", () => {
		const evaluation = evaluateL1(baseCtx(), [p1RetrievalFloor]);
		expect(evaluation.verdict).toBe("HOLD");
		expect(evaluation.advisory.map((r) => r.id)).toEqual(["P1"]);
	});
});

