				return "ran";
			},
		};
		const wrapped = k3WrapGate(tool, { gate, contextProvider: () => baseCtx(), predicates: [p8ViolationCount] });
		await expect(wrapped.execute("t1", {})).resolves.toBe("ran");
		ledger.append({ event_type: "security.deny", actor: HARNESS, action: "deny", phase: PHASE, payload: {} });
		gate.invalidateCache();
		await expect(wrapped.execute("t2", {})).rejects.toThrow(K3GateBlockedError);
		expect(executed).toBe(1);
