		expect(rows).toHaveLength(1);
		expect((rows[0].payload as { gate_id: string; verdict: string }).gate_id).toBe("tool_call.admission");
		expect((rows[0].payload as { verdict: string }).verdict).toBe("FAIL-KILL");
