		]);
		expect(unmet.allowed).toBe(false);
		expect(unmet.verdict).toBe("RECYCLE");
		expect(unmet.missing).toContain("not done: docs updated");
		const unevidenced = checkGoalCompletion([{ requirement: "tests pass", done: true, evidence_pointers: [] }]);
		expect(unevidenced.allowed).toBe(false); // done without pointers = self-report
		const empty = checkGoalCompletion([]);
		expect(empty.allowed).toBe(false); // completion without requirements = self-report
	});

	it("C granularity: the wrapped goal.complete handler refuses and ledgers instead of completing", async () => {
		const gate = new StageGate({ ledger, ledgerDir });
		const { verifyArtifact } = seedCleanPhase(); // phase itself is clean тА?only the checklist is unmet
