		expect((refusal as unknown as { missing: string[] }).missing).toContain("not done: r1");
		expect(completed).toBe(0);
		const rows = [...scanLedger(ledgerDir, (r) => r.event_type === "gate.decision")];
		expect(rows.length).toBeGreaterThan(0); // the refusal is a ledgered decision, not a silent no
		expect((rows.at(-1)?.payload as { verdict: string }).verdict).toBe("RECYCLE"); // ledgered verdict matches the handler's act
	});

	it("C granularity: a clean checklist and clean phase let goal.complete through", async () => {
		const gate = new StageGate({ ledger, ledgerDir });
		const { verifyArtifact } = seedCleanPhase();
		let completed = 0;
		const handler = createGoalCompleteGate(
