				checklistProvider: () => [{ requirement: "r1", done: true, evidence_pointers: ["ev1"] }],
			},
			async () => {
				completed++;
				return { ok: true };
			},
		);
		const out = await handler({});
		expect(out).toEqual({ ok: true });
		expect(completed).toBe(1);
