	/** Walks RUNTIME imports (type-only imports create no call-graph edge) from the gate entrypoints. */
	function runtimeImportClosure(entryFiles: string[]): Map<string, string[]> {
		const edges = new Map<string, string[]>();

		const queue = [...entryFiles];
		while (queue.length > 0) {
			const file = queue.pop()!;
			if (edges.has(file)) continue;
			const text = readFileSync(file, "utf8");
			const specifiers: string[] = [];
			const importRe = /(^|\n)\s*(import|export)\s+([^;]*?)from\s+["']([^"']+)["']/g;
			for (const m of text.matchAll(importRe)) {
				const clause = m[3];
				const spec = m[4];
				if (/^\s*type[\s{]/.test(clause)) continue; // type-only: no runtime edge
				specifiers.push(spec);
				if (spec.startsWith(".")) {
					const target = resolve(dirname(file), spec.replace(/\.js$/, ".ts"));
					queue.push(target);
				}
			}
			edges.set(file, specifiers);
		}
		return edges;
	}

