  constructor(
    public agent: Agent,
    public sessionManager: SessionManager,
    public settingsManager: SettingsManager,
  ) {}

  /** Subscribe to agent events, handle session persistence, emit to callback */
  subscribe(onEvent: (event: AgentEvent) => void): () => void;

  /** Check and perform auto-compaction if enabled */
  checkAutoCompaction(): Promise<void>;

  /** Execute manual compaction */
  compact(customInstructions?: string, signal?: AbortSignal): Promise<CompactionEntry>;

